<?php
use Illuminate\Foundation\Testing\RefreshDatabase;
use Modules\Catalog\Models\{Author,Book,Category,Publisher};
use Modules\Catalog\ValueObjects\ISBN;
use Modules\Circulation\Models\{Borrowing,LibraryActivityLog};
use Modules\Circulation\Services\CirculationService;
use Modules\Circulation\ValueObjects\Denda;
use Modules\Membership\Models\Member;
use Modules\Membership\Models\LibraryRole;
uses(RefreshDatabase::class);
function libraryFixture(): array {$p=Publisher::create(['name'=>'Penerbit Uji']);$a=Author::create(['name'=>'Penulis Uji']);$c=Category::create(['name'=>'Teknologi','slug'=>'teknologi-uji']);$sub=Category::create(['name'=>'Backend','slug'=>'backend-uji','parent_id'=>$c->id]);$b=Book::create(['title'=>'Laravel DDD','isbn'=>'9786021234567','publisher_id'=>$p->id,'stock'=>4,'available_stock'=>4]);$b->authors()->attach($a);$b->categories()->attach($sub,['added_at'=>now()]);$m=Member::create(['member_number'=>'AGT-UJI','name'=>'Penguji','email'=>'uji@example.com','joined_at'=>today(),'expires_at'=>today()->addYear(),'status'=>'active']);$role=LibraryRole::create(['name'=>'Anggota']);$m->roles()->attach($role);return compact('p','a','c','sub','b','m');}
it('validates ISBN value object and calculates fine',function(){expect((string)new ISBN('978-602-123456-7'))->toBe('9786021234567');expect(fn()=>new ISBN('bukan-isbn'))->toThrow(InvalidArgumentException::class);expect((new Denda(3,1000))->hitung())->toBe(3000);});
it('supports pivot, self reference and eager loading',function(){$f=libraryFixture();$book=Book::with(['categories.parent','authors','publisher'])->findOrFail($f['b']->id);expect($book->categories)->toHaveCount(1);expect($book->categories->first()->parent->id)->toBe($f['c']->id);expect($book->authors)->toHaveCount(1);});
it('borrows books atomically and records domain event listener',function(){$f=libraryFixture();$service=app(CirculationService::class);$borrowing=$service->borrow($f['m']->id,[['book_id'=>$f['b']->id,'quantity'=>2]]);expect($borrowing->details)->toHaveCount(1);expect($f['b']->fresh()->available_stock)->toBe(2);expect($f['m']->fresh()->active_borrowings)->toBe(1);expect(LibraryActivityLog::where('event','BookBorrowed')->count())->toBe(1);});
it('rolls back all changes when stock is insufficient',function(){$f=libraryFixture();$service=app(CirculationService::class);expect(fn()=>$service->borrow($f['m']->id,[['book_id'=>$f['b']->id,'quantity'=>99]]))->toThrow(\Illuminate\Validation\ValidationException::class);expect(Borrowing::count())->toBe(0);expect($f['b']->fresh()->available_stock)->toBe(4);expect($f['m']->fresh()->active_borrowings)->toBe(0);});
it('returns books, calculates late fine and updates membership counter',function(){$f=libraryFixture();$service=app(CirculationService::class);$b=$service->borrow($f['m']->id,[['book_id'=>$f['b']->id,'quantity'=>1]]);$b->update(['due_at'=>today()->subDays(2)]);$returned=$service->returnBorrowing($b,today()->toDateString());expect($returned->status)->toBe('returned');expect($returned->fine_amount)->toBe(2000);expect($f['b']->fresh()->available_stock)->toBe(4);expect($f['m']->fresh()->active_borrowings)->toBe(0);});
it('soft deletes and restores books members and borrowings',function(){$f=libraryFixture();$service=app(CirculationService::class);$b=$service->borrow($f['m']->id,[['book_id'=>$f['b']->id,'quantity'=>1]]);$f['b']->delete();$f['m']->delete();$b->delete();expect(Book::count())->toBe(0);expect(Member::count())->toBe(0);expect(Borrowing::count())->toBe(0);Book::withTrashed()->find($f['b']->id)->restore();Member::withTrashed()->find($f['m']->id)->restore();Borrowing::withTrashed()->find($b->id)->restore();expect(Book::count())->toBe(1);expect(Member::count())->toBe(1);expect(Borrowing::count())->toBe(1);});

it('reduces relationship query count with eager loading',function(){$f=libraryFixture();foreach([['Buku kedua','9786021234570'],['Buku ketiga','9786021234571']] as [$title,$isbn]){$book=Book::create(['title'=>$title,'isbn'=>$isbn,'publisher_id'=>$f['p']->id,'stock'=>2,'available_stock'=>2]);$book->categories()->attach($f['sub']->id,['added_at'=>now()]);}\DB::enableQueryLog();$plain=Book::all();foreach($plain as $book){$book->categories->count();} $nPlusOne=count(\DB::getQueryLog());\DB::flushQueryLog();$loaded=Book::with('categories')->get();foreach($loaded as $book){$book->categories->count();}$eager=count(\DB::getQueryLog());expect($eager)->toBeLessThan($nPlusOne);});
